import{_ as t,C as a,o as l,c as n,a3 as s,E as o}from"./chunks/framework.BnJUtV_F.js";const g=JSON.parse('{"title":"Shopping Across Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/shopping-across-sellers.md","filePath":"storefront/shopping-across-sellers.md","lastUpdated":1791380297000}'),h={name:"storefront/shopping-across-sellers.md"};function i(p,e,c,u,d,m){const r=a("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=s('<h1 id="shopping-across-sellers" tabindex="-1">Shopping Across Sellers <a class="header-anchor" href="#shopping-across-sellers" aria-label="Permalink to &quot;Shopping Across Sellers&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span></div><p>Customers shop from every seller in one store. They can see who sells a product, compare sellers who sell the same product, and pay for products from several sellers in a single checkout.</p><h2 id="who-sells-a-product" tabindex="-1">Who sells a product <a class="header-anchor" href="#who-sells-a-product" aria-label="Permalink to &quot;Who sells a product&quot;">​</a></h2><p>When the store shows seller shops publicly, customers see these on the page of a product a seller created:</p><ul><li><strong>Sold By</strong> with the seller&#39;s business name, which opens their shop page, and the seller&#39;s star rating from approved reviews;</li><li><strong>Report Product</strong>, to report a problem with the product, when the store lets customers report products. See <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><p><strong>Top Selling</strong>, a row of the seller&#39;s best-selling products, appears at the bottom of the page of every product a seller created, even when seller shops aren&#39;t public.</p>',7)),o(r,{src:"/images/shopping-across-sellers/product-sold-by.png",alt:"The Sold By block on a product page"}),e[1]||(e[1]=s('<h2 id="compare-sellers-offers" tabindex="-1">Compare sellers&#39; offers <a class="header-anchor" href="#compare-sellers-offers" aria-label="Permalink to &quot;Compare sellers&#39; offers&quot;">​</a></h2><p>When other sellers sell the same product, the product page shows a link such as <strong>2 more seller selling same product</strong>.</p><ol><li>Click the link. A page opens with the other sellers&#39; offers that are in stock, cheapest first, five at a time.</li><li>Compare each seller&#39;s price, rating and description. The rating on an offer averages all of the seller&#39;s reviews, including reviews that aren&#39;t approved yet.</li><li>For a simple or virtual product, enter the quantity on the offer you want. For a downloadable product, choose the links.</li><li>Click <strong>Add to Cart</strong>.</li></ol>',3)),o(r,{src:"/images/shopping-across-sellers/offers-page.png",alt:"Offers from several sellers for the same product"}),e[2]||(e[2]=s('<p>Click <strong>Load More</strong> to see more offers. For a product that comes in sizes or colours, choose the options on the product page first. The link then shows the offers for that choice.</p><h2 id="the-cart" tabindex="-1">The cart <a class="header-anchor" href="#the-cart" aria-label="Permalink to &quot;The cart&quot;">​</a></h2><ul><li>Each seller&#39;s product shows <strong>Sold By</strong> with the seller&#39;s business name under <strong>See Details</strong>.</li><li>The same product bought from two sellers stays on two separate lines.</li><li>Each product is charged at the price of the seller you chose.</li></ul>',3)),o(r,{src:"/images/shopping-across-sellers/cart-sellers.png",alt:"A cart with products from two sellers"}),e[3]||(e[3]=s('<h3 id="minimum-order-amounts" tabindex="-1">Minimum order amounts <a class="header-anchor" href="#minimum-order-amounts" aria-label="Permalink to &quot;Minimum order amounts&quot;">​</a></h3><p>When the store uses minimum order amounts, a seller can set the least a customer must spend with them in one order. When your products from that seller add up to less, the cart shows a message such as <strong>Minimum order amount for Urban Threads is: $25.00</strong>, and you can&#39;t check out until you add more from that seller.</p><h3 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h3><ul><li>A coupon from a seller only lowers the price of that seller&#39;s products in your cart. See <a href="./../marketing/checkout-deals">Checkout Deals</a>.</li><li>A store coupon only lowers the price of the store&#39;s own products.</li><li>Only store coupons can discount shipping.</li></ul><h2 id="checkout-and-payment" tabindex="-1">Checkout and payment <a class="header-anchor" href="#checkout-and-payment" aria-label="Permalink to &quot;Checkout and payment&quot;">​</a></h2><p>Customers check out once for the whole cart. They choose one shipping method and pay the store once, even when the products come from several sellers.</p><p>After the order is placed, each seller sees their own products from it. Sellers ship them when the store lets sellers create shipments; otherwise the store ships them. Products from different sellers can arrive in separate packages.</p><h2 id="after-the-order" tabindex="-1">After the order <a class="header-anchor" href="#after-the-order" aria-label="Permalink to &quot;After the order&quot;">​</a></h2><p>From their account, customers can:</p><ul><li>ask for a return. See <a href="./../orders/return-merchandise-authorization">Returns (RMA)</a>;</li><li>message a seller. See <a href="./../customers/communications">Communications</a>.</li></ul><p>To review a seller, customers open the seller&#39;s shop page. See <a href="./seller-shop-page#review-a-seller">Seller Shop Page</a>.</p>',11))])}const _=t(h,[["render",i]]);export{g as __pageData,_ as default};
